408	fn requested_backend() -> gpui_platform::WebBackendPreference {
409	    let search = web_sys::window()
410	        .and_then(|window| window.location().search().ok())
411	        .unwrap_or_default();
412	    if search
413	        .trim_start_matches('?')
414	        .split('&')
415	        .any(|parameter| parameter == "backend=webgpu")
416	    {
417	        gpui_platform::WebBackendPreference::WebGpu
418	    } else if search
419	        .trim_start_matches('?')
420	        .split('&')
421	        .any(|parameter| parameter == "backend=webgl")
422	    {
423	        gpui_platform::WebBackendPreference::WebGl
424	    } else {
425	        gpui_platform::WebBackendPreference::Auto
426	    }
