433	        cx.open_window(
434	            WindowOptions {
435	                window_bounds: Some(WindowBounds::Windowed(bounds)),
436	                ..Default::default()
437	            },
438	            |_, cx| cx.new(HelloWeb::new),
439	        )
440	        .expect("failed to open window");
441	        cx.activate(true);
442	    });
443	}
